export const sceneLooks={
 daylight:{name:'Bright day',sky:'#9bcce8',horizon:'#e3f3fa',sun:'#fff3d5',ground:'#698b62',fog:.35},
 sunset:{name:'Warm sunset',sky:'#c47b99',horizon:'#f7c790',sun:'#ffb57e',ground:'#685773',fog:.5},
 moonlight:{name:'Moonlit night',sky:'#182d50',horizon:'#526485',sun:'#adceff',ground:'#36495b',fog:.65},
 forest:{name:'Cozy forest',sky:'#a5ccc0',horizon:'#e0e7bc',sun:'#fff1bf',ground:'#547457',fog:.55},
 snow:{name:'Snowy world',sky:'#a4bbd5',horizon:'#f2f5fa',sun:'#edf5ff',ground:'#d2e0ed',fog:.7}
};
export const backgroundKinds={clouds:'Clouds',mountains:'Mountains',trees:'Trees',city:'City skyline',stars:'Stars',image:'Your image'};
export function createBackgroundLayer(kind='clouds'){return{id:crypto.randomUUID(),name:backgroundKinds[kind]||'Background',kind,x:0,y:0,w:100,h:100,opacity:1,parallax:kind==='clouds'?.1:kind==='mountains'?.25:.5,repeat:true,visible:true,scrollSpeed:0}}
export function validateSceneStyle(p){const image=v=>typeof v==='string'&&v.length<=3000000&&/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(v);if(p.sceneLook!==undefined&&p.sceneLook!==null&&!Object.hasOwn(sceneLooks,p.sceneLook))return false;if(p.style3d!==undefined&&(!p.style3d||!['lowpoly','smooth'].includes(p.style3d.surface)||!['chunky','balanced','fine'].includes(p.style3d.detail)||typeof p.style3d.shadows!=='boolean'||!Number.isFinite(p.style3d.fog)||p.style3d.fog<0||p.style3d.fog>1))return false;return p.backgroundLayers===undefined||Array.isArray(p.backgroundLayers)&&p.backgroundLayers.length<=20&&new Set(p.backgroundLayers.map(l=>l?.id)).size===p.backgroundLayers.length&&p.backgroundLayers.every(l=>l&&typeof l.id==='string'&&typeof l.name==='string'&&l.name.length<=80&&Object.hasOwn(backgroundKinds,l.kind)&&['x','y','w','h','opacity','parallax','scrollSpeed'].every(k=>Number.isFinite(l[k]))&&Math.abs(l.x)<=200&&Math.abs(l.y)<=200&&l.w>=5&&l.w<=400&&l.h>=5&&l.h<=400&&l.opacity>=0&&l.opacity<=1&&l.parallax>=0&&l.parallax<=1&&Math.abs(l.scrollSpeed)<=200&&typeof l.repeat==='boolean'&&typeof l.visible==='boolean'&&(l.kind!=='image'||image(l.asset)))}
export function backgroundPositions(layer,project,bounds={x:0,y:0,w:960,h:540},distance=0,time=0){const width=project.width||960,height=project.height||540,w=width*layer.w/100,h=height*layer.h/100,y=height*layer.y/100+bounds.y*(1-layer.parallax);let x=width*layer.x/100+bounds.x*(1-layer.parallax)-distance*layer.parallax+time*layer.scrollSpeed;if(!layer.repeat)return[{x,y,w,h}];x=bounds.x+((x-bounds.x)%w+w)%w-w;const count=Math.min(100,Math.ceil(bounds.w/w)+2);return Array.from({length:count},(_,i)=>({x:x+i*w,y,w,h}))}
const images=new Map();
export function paintBackgroundLayers(ctx,project,bounds,distance=0,time=0){const look=sceneLooks[project.sceneLook]||sceneLooks.daylight;for(const layer of project.backgroundLayers||[]){if(!layer.visible)continue;ctx.save();ctx.globalAlpha=layer.opacity;for(const p of backgroundPositions(layer,project,bounds,distance,time)){ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.w/960,p.h/540);paintLayer(ctx,layer,look);ctx.restore()}ctx.restore()}}
export function paintSceneSky(ctx,project){const look=sceneLooks[project.sceneLook];if(!look)return;const gradient=ctx.createLinearGradient(0,0,0,project.height||540);gradient.addColorStop(0,look.sky);gradient.addColorStop(1,look.horizon);ctx.fillStyle=gradient;ctx.fillRect(0,0,project.width||960,project.height||540)}
function paintLayer(ctx,layer,look){if(layer.kind==='image'){let image=images.get(layer.asset);if(!image){image=new Image();image.onload=()=>window.dispatchEvent(new Event('playform-asset-ready'));image.src=layer.asset;images.set(layer.asset,image)}if(image.complete&&image.naturalWidth)ctx.drawImage(image,0,0,960,540);return}if(layer.kind==='clouds'){ctx.fillStyle='#ffffff';for(const[x,y,s]of[[110,80,1],[400,150,.65],[730,65,1.2]]){ctx.beginPath();ctx.ellipse(x,y,60*s,15*s,0,0,Math.PI*2);ctx.ellipse(x-20*s,y-13*s,25*s,22*s,0,0,Math.PI*2);ctx.ellipse(x+15*s,y-22*s,32*s,28*s,0,0,Math.PI*2);ctx.fill()}}else if(layer.kind==='mountains'){for(const[x,y,w,h]of[[-130,540,500,270],[180,540,550,340],[570,540,560,260]]){ctx.fillStyle=look.ground;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+w*.5,y-h);ctx.lineTo(x+w,y);ctx.closePath();ctx.fill();ctx.fillStyle=look.horizon;ctx.beginPath();ctx.moveTo(x+w*.5,y-h);ctx.lineTo(x+w*.35,y-h*.7);ctx.lineTo(x+w*.6,y-h*.75);ctx.closePath();ctx.fill()}}else if(layer.kind==='trees'){for(let i=0;i<12;i++){const x=i*86+20,h=130+(i*47)%160;ctx.fillStyle='#4d5144';ctx.fillRect(x-5,540-h*.5,10,h*.5);ctx.fillStyle=look.ground;for(let tier=0;tier<3;tier++){const y=540-h+tier*h*.22,w=35+tier*9;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-w,y+h*.55);ctx.lineTo(x+w,y+h*.55);ctx.closePath();ctx.fill()}}}else if(layer.kind==='city'){for(let i=0;i<18;i++){const x=i*58,h=80+i*67%210;ctx.fillStyle=look.ground;ctx.fillRect(x,540-h,51,h);ctx.fillStyle=look.horizon;for(let row=0;row<h/25-1;row++)for(let col=0;col<3;col++)if((row+col+i)%3)ctx.fillRect(x+8+col*13,550-h+row*25,6,10)}}else if(layer.kind==='stars'){ctx.fillStyle='#fff4cb';for(let i=0;i<90;i++){const x=(i*137+13)%960,y=(i*83+21)%400,s=i%6===0?3:1.3;ctx.beginPath();ctx.arc(x,y,s,0,Math.PI*2);ctx.fill()}}}
